import{c as a,Z as i,Q as e,j as l,m as r,o as u}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"硕鼠","description":"","frontmatter":{"title":"硕鼠","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/9.md","filePath":"books/shici/shijing/9.md"}'),s={name:"books/shici/shijing/9.md"};function n(h,o,q,p,c,d){const t=i("PoemNav");return e(),l("div",null,[o[0]||(o[0]=r('<h1 id="硕鼠" tabindex="-1">硕鼠 <a class="header-anchor" href="#硕鼠" aria-label="Permalink to &quot;硕鼠&quot;">​</a></h1><p><strong>[先秦] 佚名</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。</p><p>硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。</p><p>硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永号？</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>硕鼠：大老鼠，比喻剥削者</li><li>无：不要</li><li>黍：黄米</li><li>三岁：多年</li><li>贯：侍奉，供养</li><li>女：通&quot;汝&quot;，你</li><li>莫我肯顾：不肯照顾我</li><li>逝：通&quot;誓&quot;</li><li>适：到……去</li><li>乐土：快乐的地方</li><li>爰：于是</li><li>所：处所，安居之地</li><li>德：感激</li><li>直：通&quot;值&quot;，报酬</li><li>劳：慰劳</li><li>郊：郊外</li><li>永号：长声叹息</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>大老鼠啊大老鼠，不要吃我的黄米！多年供养你，你却不肯照顾我。发誓要离开你，到那乐土去。乐土啊乐土，那才是我安居的地方。</p><p>大老鼠啊大老鼠，不要吃我的麦子！多年供养你，你却不肯感激我。发誓要离开你，到那乐国去。乐国啊乐国，那才是我得到报酬的地方。</p><p>大老鼠啊大老鼠，不要吃我的禾苗！多年供养你，你却不肯慰劳我。发誓要离开你，到那乐郊去。乐郊啊乐郊，谁还会长声叹息呢？</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《诗经》中的名篇，以大老鼠比喻剥削者，表达了人民对剥削者的不满和对理想社会的向往，是中国古代最早的讽刺诗之一。</p><p>全诗三章，结构相似，反复咏唱。每章都以&quot;硕鼠硕鼠&quot;开头，将剥削者比作大老鼠，形象生动，感情强烈。&quot;无食我黍&quot;&quot;无食我麦&quot;&quot;无食我苗&quot;，写剥削者对人民的掠夺，从成熟的粮食到未熟的禾苗，层层递进，表现了剥削的残酷。</p><p>&quot;三岁贯女，莫我肯顾&quot;，写人民多年供养剥削者，却得不到丝毫的照顾和感激。这种不公平的待遇，激起了人民的反抗意识。</p><p>&quot;逝将去女，适彼乐土&quot;，写人民决心离开剥削者，寻找理想的乐土。&quot;乐土&quot;&quot;乐国&quot;&quot;乐郊&quot;，是人民对理想社会的向往，那里没有剥削，人人安居乐业。</p><p>全诗语言质朴，感情强烈，将人民的苦难和对理想的向往表现得淋漓尽致，是中国古代现实主义诗歌的典范之作。</p><hr><h2 id="关于《诗经》" tabindex="-1">关于《诗经》 <a class="header-anchor" href="#关于《诗经》" aria-label="Permalink to &quot;关于《诗经》&quot;">​</a></h2><blockquote><p>《诗经》是中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为&quot;风&quot;&quot;雅&quot;&quot;颂&quot;三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。</p><p><a href="/books/shici/shijing/1.html">查看《诗经》更多作品 →</a></p></blockquote>',21)),u(t)])}const b=a(s,[["render",n]]);export{m as __pageData,b as default};
